/**
 * County metrics.
 *
 * There is exactly one county-level metric in HALISIA that is a real
 * measurement: population density, computed from the KNBS 2019 Census figures
 * already held in `kenya-county-facts.ts` divided by each county's gazetted
 * area.
 *
 * Until now this module also published a "livability index", a "YoY growth"
 * figure and a "water reliability" score. None of the three had a data source
 * anywhere in this codebase. All three were generated by hashing the county
 * code through a trigonometric function, then presented with confidence badges
 * as though they had been measured. They are gone. Nothing that cannot be
 * traced to a published source is shown as a figure.
 *
 * To add a metric back, give it a real source, add the provenance string to
 * METRIC_SOURCES, and widen `CountyMetric`. Never restore a generated number.
 */

import { KENYA_COUNTY_FACTS } from "@/lib/kenya-county-facts";

/** Every metric HALISIA can currently support with a published source. */
export type CountyMetric = "population";

export const METRIC_LABELS: Record<CountyMetric, string> = {
  population: "Population density",
};

export const METRIC_UNITS: Record<CountyMetric, string> = {
  population: "people / km²",
};

/** Where each metric comes from, in words a reader can check. */
export const METRIC_SOURCES: Record<CountyMetric, string> = {
  population: "KNBS 2019 Kenya Population and Housing Census, divided by the gazetted county area.",
};

/** Short provenance line for the one metric on the map and in exports. */
export const DENSITY_PROVENANCE =
  "KNBS 2019 Census population ÷ gazetted county area. Census night, 24/25 August 2019.";

/**
 * People per square kilometre, from the 2019 census. Returns null when the
 * county is unknown or its area is missing, so a caller can never divide by
 * zero into a plausible-looking number.
 */
export function populationDensity(code: number): number | null {
  const facts = KENYA_COUNTY_FACTS[code];
  if (!facts || !facts.areaKm2 || !facts.population2019) return null;
  return facts.population2019 / facts.areaKm2;
}

/** Rounded density, or 0 when the county has no census figure. */
export function metricValue(code: number, metric: CountyMetric): number {
  if (metric === "population") return Math.round(populationDensity(code) ?? 0);
  return 0;
}

export function countyMetrics(code: number): Record<CountyMetric, number> {
  return { population: metricValue(code, "population") };
}

/**
 * Colour-ramp position, 0..1, on a logarithmic scale.
 *
 * Kenyan county densities span roughly 6 people/km² (Marsabit) to 6,300
 * (Nairobi) — a factor of about a thousand. On a linear ramp every county
 * except Nairobi and Mombasa collapses into the same colour, which reads as
 * "no data" rather than "low density". A log scale keeps the whole range
 * legible without altering a single figure.
 */
let rampBounds: { lo: number; hi: number } | null = null;
function bounds(): { lo: number; hi: number } {
  if (rampBounds) return rampBounds;
  const values = Object.keys(KENYA_COUNTY_FACTS)
    .map((k) => populationDensity(Number(k)))
    .filter((v): v is number => v != null && v > 0);
  rampBounds = values.length
    ? { lo: Math.min(...values), hi: Math.max(...values) }
    : { lo: 1, hi: 1 };
  return rampBounds;
}

export function metricRampT(code: number, metric: CountyMetric): number {
  if (metric !== "population") return 0;
  const v = populationDensity(code);
  if (v == null || v <= 0) return 0;
  const { lo, hi } = bounds();
  if (hi <= lo) return 0.5;
  const t = (Math.log(v) - Math.log(lo)) / (Math.log(hi) - Math.log(lo));
  return Math.min(1, Math.max(0, t));
}

/**
 * Confidence in a metric. The census is a national statistical release, so a
 * county with a census figure is "high". A county without one is "low", and
 * "low" always appears next to "Not recorded", never next to a number.
 */
export function confidence(code: number, metric: CountyMetric): "low" | "med" | "high" {
  if (metric !== "population") return "low";
  return populationDensity(code) == null ? "low" : "high";
}

export function formatMetric(metric: CountyMetric, v: number): string {
  if (metric === "population") {
    if (!Number.isFinite(v) || v <= 0) return "Not recorded";
    return `${new Intl.NumberFormat("en-KE").format(Math.round(v))}/km²`;
  }
  return "Not recorded";
}
